int64_t p_map_keys(PMap* m) {
    PVec* v = p_vec_new();
    for (int64_t i = 0; i < m->len; i++)
        p_vec_push(v, (void*)m->keys[i]);
    return (int64_t)v;
}

int64_t p_map_values(PMap* m) {
    PVec* v = p_vec_new();
    for (int64_t i = 0; i < m->len; i++) {
        p_vec_push(v, (void*)m->vals[i]);
    }
    return (int64_t)v;
}

